{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 무단방치 자전거로 가져간 자전거를 다시 찾는 방법",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제10조제2항에 따르면, 구청장은 주차 후 동일 장소에 무단으로 10일 이상 방치된 자전거에 대해 소유자나 위탁자에게 무단방치 여부를 확인하고, 무단방치로 판명된 때에는 법 제20조 및 영 제11조에 따라 처분할 수 있습니다. 따라서 이미 무단방치로 확인되어 처분 절차가 진행된 자전거라면, 조례에서 정한 반환 절차는 별도로 규정되어 있지 않으므로 구청에 해당 자전거의 처리 현황을 문의하는 방식으로 확인해야 합니다.",
          "b_ids": "자전거:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
